import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test(
    "The same vendor name is allowed in a different tenant",
    { tag: "@VEN-04" },
    async ({ apiAs }) => {
      // Arrange: signed in as a Northwind member (Background)
      const northwind = await apiAs("member");
      // Given a vendor named "Acme Freight" exists in tenant "Globex Procurement"
      const globex = await apiAs("otherTenant");
      const vendorName = uniqueName("Acme Freight");

      const existing = await globex.post("/api/vendors", {
        data: {
          name: vendorName,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });
      expect(existing.status()).toBe(201);

      // When I create a vendor named "Acme Freight" in category "logistics"
      // with contact "ops@acmefreight.example" in my own tenant
      const response = await northwind.post("/api/vendors", {
        data: {
          name: vendorName,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });

      // Then the response status is 201
      expect(response.status()).toBe(201);
      const created = await response.json();
      expect(created.name).toBe(vendorName);
      expect(created.id).not.toBe((await existing.json()).id);
    },
  );
});
